/* StudioSat loader — production can replace this file with official hls.js 1.7.3 via scripts/fetch-hls-vendor.sh */
(function(){
  if(window.Hls){window.dispatchEvent(new CustomEvent('studiosat:hls-ready'));return;}
  var sources=['https://cdn.jsdelivr.net/npm/hls.js@1.7.3/dist/hls.min.js','https://unpkg.com/hls.js@1.7.3/dist/hls.min.js'];
  var i=0;
  function next(){
    if(i>=sources.length){window.dispatchEvent(new CustomEvent('studiosat:hls-ready',{detail:{ok:false}}));return;}
    var s=document.createElement('script');s.src=sources[i++];s.async=true;s.crossOrigin='anonymous';
    s.onload=function(){window.dispatchEvent(new CustomEvent('studiosat:hls-ready',{detail:{ok:!!window.Hls}}));};
    s.onerror=next;document.head.appendChild(s);
  }
  next();
})();
